// Exercises on the same physical machine share one saved base weight.
function mwKey(name){return /^Smith machine /.test(name)?'Smith machine':/^(Machine hack squat|Hack squat( calf raise)?)$/.test(name)?'Hack squat':name;}
function migrateMW(){let ch=false;Object.keys(ST.mw).forEach(k=>{const g=mwKey(k);if(g!==k){if(ST.mw[g]===undefined)ST.mw[g]=ST.mw[k];delete ST.mw[k];ch=true;}});if(ch)saveData();}
// v2.10 renamed 118 built-in exercises to the names MuscleWiki uses. Saved data
// is keyed by exercise name, so every load and every restore passes through
// migrateExNames(); it is a no-op once the old names are gone. Images keep
// their original file names (EX_OLD_NAME) so phones don't re-download them.
