const EX_OLD_NAME={};Object.keys(EX_RENAMES).forEach(o=>{EX_OLD_NAME[EX_RENAMES[o]]=o;});
function exRenamer(){const own=new Set((CFG.customExercises||[]).map(e=>e.name));return n=>(typeof n==='string'&&EX_RENAMES[n]&&!own.has(n))?EX_RENAMES[n]:n;}
function renameKeys(o,rn){let ch=false;if(!o||typeof o!=='object')return ch;Object.keys(o).forEach(k=>{const n=rn(k);if(n!==k){if(o[n]===undefined)o[n]=o[k];delete o[k];ch=true;}});return ch;}
function renameExList(list,rn){let ch=false;(Array.isArray(list)?list:[]).forEach(e=>{const t=e&&e.ex?e.ex:e;if(t&&typeof t==='object'){const n=rn(t.name);if(n!==t.name){t.name=n;ch=true;}}});return ch;}
function migrateExNames(){
  const rn=exRenamer();let ch=false;
  (ST.history||[]).forEach(h=>{if(h&&renameExList(h.exercises,rn))ch=true;});
  Object.keys(CFG.customDays||{}).forEach(d=>{const l=CFG.customDays[d];if(Array.isArray(l))l.forEach((n,i)=>{const m=rn(n);if(m!==n){l[i]=m;ch=true;}});});
  Object.values(CFG.dayPlan||{}).forEach(p=>{if(renameKeys(p,rn))ch=true;});
  if(renameKeys(CFG.syncDismiss,rn))ch=true;
  if(renameKeys(ST.mw,n=>mwKey(rn(n))))ch=true;
  return ch;
}

